1	// Proprietary in-portal DB manager — query transport to a hosting node's MySQL.
2	//
3	// SECURITY MODEL (read before touching this file):
4	//
5	//   * ISOLATION IS THE MYSQL GRANT, NOT AN APP CHECK. Every query runs
6	//     authenticated as the account's SCOPED manager user (`<username>_mgr`),
7	//     which is granted on `<username>\_%`.* ONLY (see buildDbMgrGrantSql). MySQL
8	//     itself refuses that user any access to another tenant's databases, to the
9	//     `mysql`/`sys`/`performance_schema` system schemas, and — being a db-scoped
10	//     grant — to FILE/PROCESS/SUPER (so no LOAD_FILE / INTO OUTFILE file reads).
11	//     `information_schema` stays readable but MySQL filters its rows to objects
12	//     the connecting user can see, i.e. this account's own databases. The app
13	//     ALSO validates the target db belongs to the account (defence in depth), but
14	//     even a bug there cannot breach the grant.
15	//
16	//   * PROTOCOL-LEVEL TRANSPORT — NO `mysql` CLI, EVER. The customer's SQL is run
17	//     through the `mysql2` protocol driver, which speaks the MySQL wire protocol
18	//     directly. It is NOT a command-line client, so it has NO in-band
19	//     meta-command interpreter: `\!` (shell-out), `\.`/`source` (read a node
20	//     file), `\T`/`tee` (write a node file) are CLI-only constructs and are sent
21	//     verbatim to the server as ordinary (invalid) SQL — they never execute on
22	//     the node. This is the fix for the mysql-CLI meta-command RCE: there is no
23	//     client-side interpreter to abuse, and the session authenticates as the
24	//     scoped `_mgr` user (never root), so the MySQL grant is the sole boundary.
25	//
26	//   * WHY WE STILL SSH AS ROOT (BUT ONLY TO TUNNEL). The node's MySQL is bound to
27	//     localhost and never exposed. We reach it by opening the platform's existing
28	//     root SSH connection (same credential the provisioner uses) and asking it to
29	//     `forwardOut` a direct-tcpip channel to 127.0.0.1:3306 on the node. That
30	//     channel is handed to `mysql2` as its socket. Root SSH is used ONLY as an
31	//     encrypted tunnel to localhost:3306 — it never runs a shell command and
32	//     never launches a mysql client, so the tenant's SQL can only ever reach the
33	//     MySQL server as the scoped, grant-confined user.
34	//
35	//   * SQL IS NEVER INTERPOLATED INTO A SHELL, NOR A CLI ARGV. Identifiers we
36	//     generate (db name, mgr user) are charset-validated; the mgr password is a
37	//     generated `[A-Za-z0-9]` secret passed only over the authenticated wire
38	//     handshake. The whole run is byte-capped, row-capped, and bounded by a
39	//     server-side statement cap AND a JS-side timeout that tears the connection
40	//     down, so a runaway/huge query can't hang or OOM us.
41	//
42	// This module is plain (non-"use server") + synchronous-friendly so the server
43	// actions in lib/actions-hosting-db.ts can call it directly, exactly like
44	// lib/hosting-fs.ts does for the file manager.
45	
46	import { Client, type ClientChannel } from "ssh2";
47	import mysql from "mysql2/promise";
48	import { decryptSecret } from "./crypto-box";
49	import { isValidDbIdentifier } from "./hosting";
50	
51	export type DbNodeTarget = {
52	  sshHost: string;
53	  sshPort: number;
54	  rootPassword: string;
55	  mgrUser: string;
56	  mgrPassword: string;
57	};
58	
59	/** Build the transport target for an account: the node's root SSH credential (to
60	 *  open the tunnel to localhost:3306) plus the account's scoped manager MySQL
61	 *  credential (what the mysql2 session actually authenticates as). Returns null
62	 *  until the manager user has been provisioned on the node. Lives in this plain
63	 *  module (not the "use server" actions file) because it is synchronous. */
64	export function dbTargetFor(a: {
65	  node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null };
66	  dbMgrUser: string | null;
67	  dbMgrPassEnc: string | null;
68	}): DbNodeTarget | null {
69	  const rootPassword = a.node.rootPasswordEnc ? decryptSecret(a.node.rootPasswordEnc) : null;
70	  const mgrPassword = a.dbMgrPassEnc ? decryptSecret(a.dbMgrPassEnc) : null;
71	  if (!rootPassword || !a.dbMgrUser || !mgrPassword) return null;
72	  return { sshHost: a.node.sshHost, sshPort: a.node.sshPort, rootPassword, mgrUser: a.dbMgrUser, mgrPassword };
73	}
74	
75	const CONNECT_TIMEOUT_MS = 20_000;
76	/** Hard ceiling on a single query, enforced on BOTH ends: a server-side statement
77	 *  cap (max_execution_time / max_statement_time) and a JS timer that destroys the
78	 *  mysql2 connection + tears down the SSH channel. */
79	const QUERY_TIMEOUT_S = 15;
80	const QUERY_TIMEOUT_MS = (QUERY_TIMEOUT_S + 5) * 1000;
81	/** Cap the bytes we retain from a result so a `SELECT * FROM huge` can't OOM the
82	 *  app node — we stop reading (destroy the connection) and mark it truncated. */
83	const MAX_OUTPUT_BYTES = 2 * 1024 * 1024; // 2 MiB
84	/** Cap on the SQL we will ship to the node (a sane upper bound; the UI edits are
85	 *  tiny and even a pasted query is far under this). */
86	export const MAX_SQL_BYTES = 64 * 1024;
87	
88	export type QueryResult = {
89	  columns: string[];
90	  rows: string[][];
91	  /** true when we stopped at MAX_OUTPUT_BYTES / the row cap and more data exists. */
92	  truncated: boolean;
93	  /** non-null on a MySQL/transport error (already trimmed for display). */
94	  error: string | null;
95	  /** ms the query took end-to-end (for the UI). */
96	  elapsedMs: number;
97	};
98	
99	function connectRoot(t: DbNodeTarget): Promise<Client> {
100	  const conn = new Client();
101	  return new Promise<Client>((resolve, reject) => {
102	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
103	    conn
104	      .on("ready", () => { clearTimeout(timer); resolve(conn); })
105	      .on("error", (e) => { clearTimeout(timer); reject(e); })
106	      .connect({ host: t.sshHost, port: t.sshPort, username: "root", password: t.rootPassword, readyTimeout: CONNECT_TIMEOUT_MS });
107	  });
108	}
109	
110	/** Open a direct-tcpip channel from the root SSH connection to the node's
111	 *  localhost MySQL. The returned Channel is a duplex stream we hand to mysql2 as
112	 *  its socket — MySQL stays bound to localhost on the node (never exposed). */
113	function forwardMysqlChannel(conn: Client): Promise<ClientChannel> {
114	  return new Promise<ClientChannel>((resolve, reject) => {
115	    const timer = setTimeout(() => reject(new Error("SSH tunnel to MySQL timed out")), CONNECT_TIMEOUT_MS);
116	    conn.forwardOut("127.0.0.1", 0, "127.0.0.1", 3306, (err, channel) => {
117	      clearTimeout(timer);
118	      if (err) return reject(err);
119	      resolve(channel);
120	    });
121	  });
122	}
123	
124	/**
125	 * Run one statement of SQL against `dbName` as the scoped manager user and return
126	 * the result set (or an error). The SQL is executed through the mysql2 protocol
127	 * driver over an SSH-forwarded channel to the node's localhost MySQL — there is
128	 * NO mysql CLI in the path, so client-side meta-commands (`\!`, source, tee)
129	 * cannot execute; they reach the server as ordinary SQL. `multipleStatements` is
130	 * off, so no stacked queries. Non-SELECT statements produce no rows (columns
131	 * empty) — the caller reports a generic success.
132	 */
133	export async function runScopedSql(t: DbNodeTarget, dbName: string, sql: string): Promise<QueryResult> {
134	  const started = Date.now();
135	  // Re-assert the shape of every value we authenticate/connect with (the caller
136	  // validates too — belt and braces). The mgr user + db name are OUR generated
137	  // identifiers; the password is generated [A-Za-z0-9].
138	  if (!isValidDbIdentifier(dbName)) return errResult(started, "invalid database name");
139	  if (!isValidDbIdentifier(t.mgrUser)) return errResult(started, "invalid manager user");
140	  if (!/^[A-Za-z0-9]{1,64}$/.test(t.mgrPassword)) return errResult(started, "invalid manager credential");
141	  const sqlText = String(sql ?? "");
142	  if (Buffer.byteLength(sqlText, "utf8") > MAX_SQL_BYTES) return errResult(started, "query too large");
143	
144	  let conn: Client | null = null;
145	  let channel: ClientChannel | null = null;
146	  let connection: mysql.Connection | null = null;
147	  try {
148	    conn = await connectRoot(t);
149	    channel = await forwardMysqlChannel(conn);
150	    // Authenticate as the SCOPED manager user over the forwarded stream. No CLI,
151	    // no root MySQL session — the grant on `<username>\_%`.* is the only boundary.
152	    connection = await mysql.createConnection({
153	      stream: channel,
154	      user: t.mgrUser,
155	      password: t.mgrPassword,
156	      database: dbName,
157	      multipleStatements: false, // one statement per run — no stacked-query surface
158	      dateStrings: true,         // DATE/DATETIME/TIMESTAMP as strings (match old display)
159	      supportBigNumbers: true,
160	      bigNumberStrings: true,    // no precision loss on BIGINT / DECIMAL
161	      connectTimeout: CONNECT_TIMEOUT_MS,
162	      charset: "utf8mb4_general_ci",
163	    });
164	    // Best-effort server-side statement cap. MySQL uses max_execution_time (ms,
165	    // SELECTs only); MariaDB uses max_statement_time (seconds). The value is our
166	    // own integer constant (no injection surface). Either may be absent — the JS
167	    // timeout below is the hard guard regardless.
168	    await connection.query(`SET SESSION max_execution_time = ${QUERY_TIMEOUT_S * 1000}`).catch(() => { /* */ });
169	    await connection.query(`SET SESSION max_statement_time = ${QUERY_TIMEOUT_S}`).catch(() => { /* */ });
170	
171	    return await streamQuery(connection, sqlText, started);
172	  } catch (e) {
173	    return errResult(started, e instanceof Error ? e.message : String(e));
174	  } finally {
175	    // Always tear everything down: mysql2 connection, forwarded channel, SSH.
176	    try { if (connection) await connection.end(); } catch { try { connection?.destroy(); } catch { /* */ } }
177	    try { channel?.end(); } catch { /* */ }
178	    try { conn?.end(); } catch { /* */ }
179	  }
180	}
181	
182	/**
183	 * Execute one statement via the mysql2 streaming (event-emitter) API on the
184	 * underlying core connection, enforcing the row + byte caps and a hard JS timeout.
185	 * Streaming (rather than a buffered `[rows]` await) lets us stop the server mid
186	 * result-set — destroying the connection — the instant either cap is hit, so a
187	 * `SELECT * FROM huge` can neither OOM us nor stay on the wire. `rowsAsArray`
188	 * yields positional arrays that preserve duplicate column names.
189	 */
190	function streamQuery(connection: mysql.Connection, sql: string, started: number): Promise<QueryResult> {
191	  return new Promise<QueryResult>((resolve) => {
192	    // The promise wrapper exposes the callback-style core connection as `.connection`;
193	    // only the core connection returns the streaming Query event-emitter.
194	    const core = (connection as unknown as { connection: any }).connection;
195	    const columns: string[] = [];
196	    const rows: string[][] = [];
197	    let bytes = 0;
198	    let truncated = false;
199	    let settled = false;
200	
201	    const finish = (r: QueryResult) => {
202	      if (settled) return;
203	      settled = true;
204	      clearTimeout(timer);
205	      resolve(r);
206	    };
207	    const finishOk = () => finish({ columns, rows, truncated, error: null, elapsedMs: Date.now() - started });
208	    const stopAtCap = () => {
209	      truncated = true;
210	      // Halt further transfer, then resolve with what we have.
211	      try { core.destroy(); } catch { /* */ }
212	      finishOk();
213	    };
214	
215	    const timer = setTimeout(() => {
216	      try { core.destroy(); } catch { /* */ }
217	      finish(errResult(started, "query timed out"));
218	    }, QUERY_TIMEOUT_MS);
219	
220	    let q: any;
221	    try {
222	      q = core.query({ sql, rowsAsArray: true });
223	    } catch (e) {
224	      return finish(errResult(started, e instanceof Error ? e.message : String(e)));
225	    }
226	    q.on("error", (err: Error) => finish(errResult(started, err?.message ?? String(err))));
227	    q.on("fields", (fields: any) => {
228	      // Emitted once per result set for SELECT-like statements; absent for OK packets.
229	      if (Array.isArray(fields)) for (const f of fields) columns.push(String(f?.name ?? ""));
230	    });
231	    q.on("result", (row: any) => {
232	      if (settled || truncated) return;
233	      // Non-SELECT statements emit an OK/result packet (not an array) → no rows.
234	      if (!Array.isArray(row)) return;
235	      if (rows.length >= MAX_ROWS) return stopAtCap();
236	      const out = new Array<string>(row.length);
237	      for (let i = 0; i < row.length; i++) {
238	        const s = cellToString(row[i]);
239	        out[i] = s;
240	        bytes += Buffer.byteLength(s, "utf8");
241	      }
242	      rows.push(out);
243	      if (bytes >= MAX_OUTPUT_BYTES) return stopAtCap();
244	    });
245	    q.on("end", () => finishOk());
246	  });
247	}
248	
249	/** Convert a mysql2 cell value to the display string the UI expects. SQL NULL maps
250	 *  to the NULL sentinel (the grid renders it as a muted "NULL"); dates already
251	 *  arrive as strings (dateStrings:true); Buffers are decoded as UTF-8. */
252	function cellToString(v: unknown): string {
253	  if (v === null || v === undefined) return NULL_CELL;
254	  if (typeof v === "string") return v;
255	  if (Buffer.isBuffer(v)) return v.toString("utf8");
256	  if (v instanceof Date) return v.toISOString();
257	  return String(v);
258	}
259	
260	function errResult(started: number, message: string): QueryResult {
261	  return { columns: [], rows: [], truncated: false, error: sanitizeError(message), elapsedMs: Date.now() - started };
262	}
263	
264	/** Trim + de-noise a MySQL/transport error for display (drop the leading
265	 *  `ERROR 1064 (42000) at line 1:` prefix mysql prints in batch mode). */
266	export function sanitizeError(message: string): string {
267	  return String(message ?? "")
268	    .replace(/^ERROR\s+\d+\s+\([0-9A-Z]+\)\s+at line \d+:\s*/i, "")
269	    .replace(/^ERROR\s+\d+\s+\([0-9A-Z]+\):\s*/i, "")
270	    .trim()
271	    .slice(0, 500) || "Query failed.";
272	}
273	
274	/** Row cap. We hard-limit rows so a caller that forgets a LIMIT still can't pull
275	 *  an unbounded set into memory/over the wire. */
276	export const MAX_ROWS = 1000;
277	
278	/** Sentinel a NULL cell resolves to (chosen so it can't collide with a real
279	 *  value; the UI renders it as a muted "NULL"). */
280	export const NULL_CELL = " NULL ";
281	
282	// ---- Safe SQL builders for the browse UI ------------------------------------
283	// The table name here is USER-CHOSEN. MySQL cannot bind an identifier as a
284	// prepared-statement parameter, so it only ever lands inside a backtick-quoted
285	// identifier in SQL that travels over the mysql2 wire (never a shell, never a
286	// CLI argv). We (1) accept only a conservative identifier charset, (2) double any
287	// backtick, and (3) the caller additionally checks membership against SHOW TABLES,
288	// so a value can neither break out of the quotes nor name a table the user can't
289	// see. LIMIT/OFFSET are integer-clamped and embedded as plain numbers.
290	
291	const TABLE_IDENT_RE = /^[A-Za-z0-9_$ .-]{1,64}$/;
292	export function isPlausibleTableName(name: string): boolean {
293	  return TABLE_IDENT_RE.test(String(name ?? ""));
294	}
295	
296	/** Quote an identifier for embedding between backticks (double internal ``` ` ```). */
297	export function quoteIdent(name: string): string {
298	  return "`" + String(name).replace(/`/g, "``") + "`";
299	}
300	
301	/** Page size for the row browser (rows per page). */
302	export const BROWSE_PAGE_SIZE = 50;
303	
304	export function showTablesSql(): string {
305	  return "SHOW TABLES;";
306	}
307	
308	/** A bounded page of a table's rows. `offset`/`limit` are clamped to integers by
309	 *  the caller; embedded here as plain numbers (never strings). */
310	export function browseTableSql(table: string, limit: number, offset: number): string {
311	  const lim = Math.max(1, Math.min(BROWSE_PAGE_SIZE, Math.floor(limit)));
312	  const off = Math.max(0, Math.floor(offset));
313	  return `SELECT * FROM ${quoteIdent(table)} LIMIT ${lim} OFFSET ${off};`;
314	}
315	
316	export function countTableSql(table: string): string {
317	  return `SELECT COUNT(*) AS n FROM ${quoteIdent(table)};`;
318	}
