1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import {
5	  ensureDbManager,
6	  dbmgrStatus,
7	  dbmgrListDatabases,
8	  dbmgrListTables,
9	  dbmgrBrowseTable,
10	  dbmgrRunSql,
11	  type DbMgrDatabase,
12	} from "@/lib/actions-hosting-db";
13	
14	/**
15	 * Nxeon DB Studio — the PROPRIETARY, in-portal database manager (replaces the
16	 * third-party Adminer file we used to drop into the webroot). All SQL runs
17	 * server-side as the account's scoped MySQL user, so it can only ever touch this
18	 * account's own databases. Nothing here ever holds a DB credential.
19	 */
20	export function DbManager({ accountId }: { accountId: string }) {
21	  const [status, setStatus] = useState<"loading" | "provisioning" | "ready" | "error">("loading");
22	  const [statusMsg, setStatusMsg] = useState("");
23	  const [databases, setDatabases] = useState<DbMgrDatabase[]>([]);
24	  const [activeDb, setActiveDb] = useState<string>("");
25	  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
26	
27	  // Kick provisioning + load the account's databases on mount.
28	  useEffect(() => {
29	    let cancelled = false;
30	    (async () => {
31	      const [ens, list] = await Promise.all([ensureDbManager(accountId), dbmgrListDatabases(accountId)]);
32	      if (cancelled) return;
33	      if (list.databases) {
34	        setDatabases(list.databases);
35	        const firstActive = list.databases.find((d) => d.status === "ACTIVE") ?? list.databases[0];
36	        if (firstActive) setActiveDb(firstActive.name);
37	      }
38	      if (ens.error) { setStatus("error"); setStatusMsg(ens.error); return; }
39	      if (ens.ready) { setStatus("ready"); return; }
40	      setStatus("provisioning");
41	    })();
42	    return () => { cancelled = true; };
43	  }, [accountId]);
44	
45	  // Poll until the manager user is provisioned on the node.
46	  useEffect(() => {
47	    if (status !== "provisioning") return;
48	    let tries = 0;
49	    pollRef.current = setInterval(async () => {
50	      tries++;
51	      const s = await dbmgrStatus(accountId);
52	      if (s.ready) { setStatus("ready"); if (pollRef.current) clearInterval(pollRef.current); return; }
53	      if (tries >= 20) { setStatus("error"); setStatusMsg("The database manager is taking longer than expected to set up. Try again shortly."); if (pollRef.current) clearInterval(pollRef.current); }
54	    }, 3000);
55	    return () => { if (pollRef.current) clearInterval(pollRef.current); };
56	  }, [status, accountId]);
57	
58	  if (databases.length === 0 && status !== "loading") {
59	    return (
60	      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-4 py-6 text-center">
61	        <p className="text-sm text-slate-300">No databases yet</p>
62	        <p className="mt-1 text-xs text-slate-500">Create a database below, then open Nxeon DB Studio to browse and query it.</p>
63	      </div>
64	    );
65	  }
66	
67	  return (
68	    <div className="rounded-xl border border-white/[0.06] bg-navy-900/50 p-4">
69	      <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
70	        <div className="flex items-center gap-2">
71	          <span className="flex h-6 w-6 items-center justify-center rounded-md bg-gradient-to-br from-accent-blue to-brand-500 text-[11px] font-bold text-white">N</span>
72	          <h3 className="text-sm font-semibold text-slate-200">Nxeon DB Studio</h3>
73	          <span className="rounded bg-white/[0.06] px-1.5 py-0.5 text-[10px] uppercase tracking-wide text-slate-400">Beta</span>
74	        </div>
75	        {databases.length > 0 && (
76	          <select
77	            value={activeDb}
78	            onChange={(e) => setActiveDb(e.target.value)}
79	            className="input max-w-[16rem] text-xs"
80	          >
81	            {databases.map((d) => (
82	              <option key={d.name} value={d.name} disabled={d.status !== "ACTIVE"}>
83	                {d.name}{d.status !== "ACTIVE" ? ` (${d.status.toLowerCase()})` : ""}
84	              </option>
85	            ))}
86	          </select>
87	        )}
88	      </div>
89	
90	      {status === "loading" && <p className="text-xs text-slate-500">Loading…</p>}
91	      {status === "provisioning" && (
92	        <p className="text-xs text-amber-300">Preparing your secure database connection… this only happens once.</p>
93	      )}
94	      {status === "error" && <p className="text-xs text-amber-300">{statusMsg}</p>}
95	
96	      {status === "ready" && activeDb && <Workbench accountId={accountId} dbName={activeDb} key={activeDb} />}
97	    </div>
98	  );
99	}
100	
101	/* ------------------------------------------------------------- Workbench --- */
102	
103	function Workbench({ accountId, dbName }: { accountId: string; dbName: string }) {
104	  const [tables, setTables] = useState<string[]>([]);
105	  const [tablesErr, setTablesErr] = useState("");
106	  const [activeTable, setActiveTable] = useState<string>("");
107	  const [view, setView] = useState<"browse" | "sql">("browse");
108	
109	  const loadTables = useCallback(async () => {
110	    setTablesErr("");
111	    const res = await dbmgrListTables(accountId, dbName);
112	    if (res.error) { setTablesErr(res.error); setTables([]); return; }
113	    setTables(res.tables ?? []);
114	  }, [accountId, dbName]);
115	
116	  useEffect(() => { loadTables(); }, [loadTables]);
117	
118	  return (
119	    <div className="grid gap-4 md:grid-cols-[13rem_1fr]">
120	      {/* Tables sidebar */}
121	      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-2">
122	        <div className="mb-2 flex items-center justify-between px-1">
123	          <span className="text-[11px] font-medium uppercase tracking-wide text-slate-500">Tables</span>
124	          <button type="button" className="text-[11px] text-brand-300 hover:underline" onClick={loadTables}>refresh</button>
125	        </div>
126	        {tablesErr && <p className="px-1 text-[11px] text-amber-300">{tablesErr}</p>}
127	        {!tablesErr && tables.length === 0 && <p className="px-1 text-[11px] text-slate-500">No tables in this database.</p>}
128	        <ul className="max-h-72 space-y-0.5 overflow-y-auto">
129	          {tables.map((t) => (
130	            <li key={t}>
131	              <button
132	                type="button"
133	                onClick={() => { setActiveTable(t); setView("browse"); }}
134	                className={`w-full truncate rounded px-2 py-1 text-left font-mono text-xs ${activeTable === t && view === "browse" ? "bg-brand-500/20 text-brand-200" : "text-slate-300 hover:bg-white/[0.04]"}`}
135	                title={t}
136	              >
137	                {t}
138	              </button>
139	            </li>
140	          ))}
141	        </ul>
142	        <button
143	          type="button"
144	          onClick={() => setView("sql")}
145	          className={`mt-2 w-full rounded px-2 py-1 text-left text-xs ${view === "sql" ? "bg-brand-500/20 text-brand-200" : "text-slate-300 hover:bg-white/[0.04]"}`}
146	        >
147	          ✎ SQL query
148	        </button>
149	      </div>
150	
151	      {/* Main pane */}
152	      <div className="min-w-0">
153	        {view === "browse" && activeTable && <BrowseTable accountId={accountId} dbName={dbName} table={activeTable} />}
154	        {view === "browse" && !activeTable && <p className="text-xs text-slate-500">Pick a table on the left to browse its rows, or open the SQL query editor.</p>}
