163	function BrowseTable({ accountId, dbName, table }: { accountId: string; dbName: string; table: string }) {
164	  const [page, setPage] = useState(0);
165	  const [data, setData] = useState<{ columns: string[]; rows: string[][]; total: number | null; pageSize: number; truncated: boolean } | null>(null);
166	  const [err, setErr] = useState("");
167	  const [busy, setBusy] = useState(false);
168	
169	  useEffect(() => { setPage(0); }, [table]);
170	
171	  useEffect(() => {
172	    let cancelled = false;
173	    setBusy(true); setErr("");
174	    dbmgrBrowseTable(accountId, dbName, table, page).then((res) => {
175	      if (cancelled) return;
176	      setBusy(false);
177	      if (res.error) { setErr(res.error); setData(null); return; }
178	      setData({ columns: res.columns ?? [], rows: res.rows ?? [], total: res.total ?? null, pageSize: res.pageSize ?? 50, truncated: !!res.truncated });
179	    });
180	    return () => { cancelled = true; };
181	  }, [accountId, dbName, table, page]);
182	
183	  const total = data?.total ?? null;
184	  const pageSize = data?.pageSize ?? 50;
185	  const maxPage = total != null ? Math.max(0, Math.ceil(total / pageSize) - 1) : (data && data.rows.length === pageSize ? page + 1 : page);
186	
187	  return (
188	    <div>
189	      <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
190	        <p className="font-mono text-sm text-slate-200">{table}{total != null && <span className="ml-2 text-xs text-slate-500">{total.toLocaleString()} rows</span>}</p>
191	        <div className="flex items-center gap-1 text-xs">
192	          <button className="btn-secondary px-2 py-0.5 text-xs disabled:opacity-40" disabled={busy || page === 0} onClick={() => setPage((p) => Math.max(0, p - 1))}>‹ Prev</button>
193	          <span className="px-1 text-slate-500">page {page + 1}</span>
194	          <button className="btn-secondary px-2 py-0.5 text-xs disabled:opacity-40" disabled={busy || page >= maxPage} onClick={() => setPage((p) => p + 1)}>Next ›</button>
195	        </div>
196	      </div>
197	      {err && <p className="text-xs text-amber-300">{err}</p>}
198	      {data && <ResultGrid columns={data.columns} rows={data.rows} truncated={data.truncated} />}
199	    </div>
200	  );
201	}
