203	/* ------------------------------------------------------------- SqlEditor --- */
204	
205	function SqlEditor({ accountId, dbName, onChanged }: { accountId: string; dbName: string; onChanged: () => void }) {
206	  const [sql, setSql] = useState("");
207	  const [busy, setBusy] = useState(false);
208	  const [err, setErr] = useState("");
209	  const [note, setNote] = useState("");
210	  const [result, setResult] = useState<{ columns: string[]; rows: string[][]; truncated: boolean } | null>(null);
211	
212	  async function run() {
213	    if (!sql.trim()) return;
214	    setBusy(true); setErr(""); setNote(""); setResult(null);
215	    const res = await dbmgrRunSql(accountId, dbName, sql);
216	    setBusy(false);
217	    if (res.error) { setErr(res.error); return; }
218	    if (res.columns.length === 0) {
219	      setNote(`Statement executed in ${res.elapsedMs} ms.`);
220	      onChanged(); // a DDL/DML may have changed the table list
221	      return;
222	    }
223	    setResult({ columns: res.columns, rows: res.rows, truncated: res.truncated });
224	    setNote(`${res.rows.length} row${res.rows.length === 1 ? "" : "s"} · ${res.elapsedMs} ms`);
225	  }
226	
227	  return (
228	    <div>
229	      <p className="mb-1 text-[11px] text-slate-500">
230	        Running against <span className="font-mono text-slate-300">{dbName}</span>. Queries run as your database user — they can only ever touch your own databases.
231	      </p>
232	      <textarea
233	        className="input h-28 w-full font-mono text-xs"
234	        placeholder="SELECT * FROM your_table LIMIT 20;"
235	        value={sql}
236	        onChange={(e) => setSql(e.target.value)}
237	        onKeyDown={(e) => { if ((e.metaKey || e.ctrlKey) && e.key === "Enter") run(); }}
238	      />
239	      <div className="mt-2 flex items-center gap-2">
240	        <button className="btn-secondary text-xs" disabled={busy || !sql.trim()} onClick={run}>{busy ? "Running…" : "Run"}</button>
241	        <span className="text-[11px] text-slate-500">⌘/Ctrl + Enter</span>
242	        {note && <span className="text-[11px] text-slate-400">{note}</span>}
243	      </div>
244	      {err && <p className="mt-2 whitespace-pre-wrap rounded border border-amber-500/30 bg-amber-500/10 px-2 py-1.5 font-mono text-[11px] text-amber-200">{err}</p>}
245	      {result && <div className="mt-3"><ResultGrid columns={result.columns} rows={result.rows} truncated={result.truncated} /></div>}
246	    </div>
247	  );
248	}
