250	/* ------------------------------------------------------------- ResultGrid --- */
251	
252	function ResultGrid({ columns, rows, truncated }: { columns: string[]; rows: string[][]; truncated: boolean }) {
253	  if (columns.length === 0) return <p className="text-xs text-slate-500">No columns.</p>;
254	  return (
255	    <div>
256	      <div className="overflow-x-auto rounded-lg border border-white/[0.06]">
257	        <table className="min-w-full text-left text-xs">
258	          <thead className="bg-white/[0.03]">
259	            <tr>
260	              {columns.map((c, i) => (
261	                <th key={i} className="whitespace-nowrap border-b border-white/[0.06] px-3 py-1.5 font-medium text-slate-300">{c}</th>
262	              ))}
263	            </tr>
264	          </thead>
265	          <tbody>
266	            {rows.length === 0 && (
267	              <tr><td colSpan={columns.length} className="px-3 py-3 text-center text-slate-500">No rows.</td></tr>
268	            )}
269	            {rows.map((r, ri) => (
270	              <tr key={ri} className="odd:bg-white/[0.01]">
271	                {columns.map((_, ci) => (
272	                  <td key={ci} className="max-w-xs truncate border-b border-white/[0.04] px-3 py-1 font-mono text-slate-400" title={cell(r[ci])}>{cell(r[ci])}</td>
273	                ))}
274	              </tr>
275	            ))}
276	          </tbody>
277	        </table>
278	      </div>
279	      {truncated && <p className="mt-1 text-[11px] text-amber-300">Results truncated — refine your query with a LIMIT or WHERE clause to see more.</p>}
280	    </div>
281	  );
282	}
