284	/** The transport maps SQL NULL to a sentinel; render it as a muted "NULL". */
285	const NULL_CELL = " NULL ";
286	function cell(v: string | undefined): string {
287	  if (v === undefined) return "";
288	  if (v === NULL_CELL) return "NULL";
289	  return v;
290	}
