// ---- Structure + parameterized DML builders (for the row editor) ------------
// Every builder below quotes identifiers with `quoteIdent` (backtick-doubled) and
// leaves user VALUES as `?` placeholders, bound by mysql2 (escaped, never string-
// concatenated). Callers MUST validate the table by membership (SHOW TABLES) and
// each column name by membership (SHOW COLUMNS) before passing it in, so a name
// can only ever be one the scoped `_mgr` user is already allowed to see.

export function showFullColumnsSql(table: string): string {
  return `SHOW FULL COLUMNS FROM ${quoteIdent(table)};`;
}

export function showIndexSql(table: string): string {
  return `SHOW INDEX FROM ${quoteIdent(table)};`;
}

export function showCreateTableSql(table: string): string {
  return `SHOW CREATE TABLE ${quoteIdent(table)};`;
}

/** `INSERT INTO t (c1,c2) VALUES (?,?)` — the caller passes one param per column,
 *  in the same order as `cols`. `cols` must be validated column names. */
export function insertRowSql(table: string, cols: string[]): string {
  const idents = cols.map(quoteIdent).join(", ");
  const marks = cols.map(() => "?").join(", ");
  return `INSERT INTO ${quoteIdent(table)} (${idents}) VALUES (${marks});`;
}

/** `UPDATE t SET c1=?,... WHERE w1<=>? AND ... LIMIT 1`. Params order is:
 *  [...set values, ...where values]. `<=>` is MySQL's NULL-safe equality so a row
 *  whose key column is NULL still matches. LIMIT 1 bounds a non-unique match. */
export function updateRowSql(table: string, setCols: string[], whereCols: string[]): string {
  const setClause = setCols.map((c) => `${quoteIdent(c)} = ?`).join(", ");
  const whereClause = whereCols.map((c) => `${quoteIdent(c)} <=> ?`).join(" AND ");
  return `UPDATE ${quoteIdent(table)} SET ${setClause} WHERE ${whereClause} LIMIT 1;`;
}

/** `DELETE FROM t WHERE w1<=>? AND ... LIMIT 1`. Params: the where values. */
export function deleteRowSql(table: string, whereCols: string[]): string {
  const whereClause = whereCols.map((c) => `${quoteIdent(c)} <=> ?`).join(" AND ");
  return `DELETE FROM ${quoteIdent(table)} WHERE ${whereClause} LIMIT 1;`;
}

