/* ─────────────────────── Structure + row editor (parameterized) ──────────────
 * These actions power the data-grid's insert / edit / delete and the "structure"
 * tab. They share the same isolation as the query surface: owner-or-admin, not
 * impersonating, owned db, rate-limited, and — crucially — every statement runs
 * through `runScopedSql` as the scoped `<username>_mgr` user over the SSH tunnel.
 * User VALUES are always bound as `?` parameters (never string-concatenated);
 * user IDENTIFIERS (table + column names) are validated by MEMBERSHIP against the
 * live table/column list before they can be backtick-quoted into SQL, so a name
 * can only ever be one the scoped user is already permitted to see. */

const SANDBOX_STRUCTURE: DbMgrStructure = {
  columns: [
    { name: "id", type: "int(11)", nullable: false, key: "PRI", default: null, extra: "auto_increment", comment: "" },
    { name: "name", type: "varchar(255)", nullable: false, key: "", default: null, extra: "", comment: "" },
    { name: "created_at", type: "datetime", nullable: true, key: "", default: "CURRENT_TIMESTAMP", extra: "", comment: "" },
  ],
  indexes: [{ name: "PRIMARY", columns: ["id"], unique: true }],
  primaryKey: ["id"],
};

/** Owner-or-admin + not-impersonating + owned-db + rate-limit + ready-target
 *  preamble shared by the live-data actions. Returns a discriminated result. */
async function liveTarget(
  accountId: string,
  dbName: string,
): Promise<{ error: string } | { mode: "sandbox" } | { mode: "live"; target: DbNodeTarget }> {
  const ctx = await loadOwned(accountId);
  if ("error" in ctx) return { error: ctx.error };
  await assertNotImpersonating();
  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
  if (!rlOk(ctx.user.id, accountId)) return { error: "Too many requests — slow down a moment." };
  if (SANDBOX) return { mode: "sandbox" };
  const target = dbTargetFor(ctx.a);
  if (!target) return { error: "The database manager is still being prepared." };
  return { mode: "live", target };
}

/** Confirm `table` is one the scoped user can actually see (membership check via
 *  SHOW TABLES). The lone hard identifier boundary for the DML/structure paths. */
async function tableIsVisible(target: DbNodeTarget, dbName: string, table: string): Promise<{ error: string } | { ok: true }> {
  if (!isPlausibleTableName(table)) return { error: "Invalid table name." };
  const listed = await runScopedSql(target, dbName, showTablesSql());
  if (listed.error) return { error: listed.error };
  if (!listed.rows.map((r) => r[0]).includes(table)) return { error: "Unknown table." };
  return { ok: true };
}

/** Fetch a table's structure (columns, indexes, primary key) as the scoped user.
 *  Assumes membership has already been asserted for `table`. */
async function fetchStructure(target: DbNodeTarget, dbName: string, table: string): Promise<{ error: string } | { structure: DbMgrStructure }> {
  const cols = await runScopedSql(target, dbName, showFullColumnsSql(table));
  if (cols.error) return { error: cols.error };
  // SHOW FULL COLUMNS positional order: Field, Type, Collation, Null, Key, Default, Extra, Privileges, Comment.
  const columns: DbMgrColumn[] = cols.rows.map((r) => ({
    name: r[0],
    type: r[1],
    nullable: (r[3] ?? "").toUpperCase() === "YES",
    key: r[4] ?? "",
    default: r[5] === NULL_SENTINEL ? null : (r[5] ?? null),
    extra: r[6] ?? "",
    comment: r[8] ?? "",
  }));

  const idx = await runScopedSql(target, dbName, showIndexSql(table));
  // SHOW INDEX positional: Table, Non_unique, Key_name, Seq_in_index, Column_name, ...
  const byName = new Map<string, { name: string; unique: boolean; cols: Array<{ seq: number; col: string }> }>();
  if (!idx.error) {
    for (const r of idx.rows) {
      const keyName = r[2];
      const nonUnique = r[1] === "1";
      const seq = Number(r[3] ?? "0") || 0;
      const col = r[4];
      const entry = byName.get(keyName) ?? { name: keyName, unique: !nonUnique, cols: [] };
      entry.cols.push({ seq, col });
      byName.set(keyName, entry);
    }
  }
  const indexes: DbMgrIndex[] = [...byName.values()].map((e) => ({
    name: e.name,
    unique: e.unique,
    columns: e.cols.sort((a, b) => a.seq - b.seq).map((c) => c.col),
  }));
  const primaryKey = indexes.find((i) => i.name === "PRIMARY")?.columns
    ?? columns.filter((c) => c.key === "PRI").map((c) => c.name);

  return { structure: { columns, indexes, primaryKey } };
}

/** The sentinel a NULL cell arrives as from the transport (see hosting-db.ts). We
 *  compare against it locally so a real string value can't be mistaken for NULL. */
const NULL_SENTINEL = " NULL ";

/** Read a table's structure (columns/types/keys/indexes) for the "structure" tab
 *  and to power the insert/edit forms. Owner-or-admin + not-impersonating. */
export async function dbmgrTableStructure(accountId: string, dbName: string, table: string): Promise<{ error?: string; structure?: DbMgrStructure }> {
  const lt = await liveTarget(accountId, dbName);
  if ("error" in lt) return { error: lt.error };
  if (lt.mode === "sandbox") return { structure: SANDBOX_STRUCTURE };
  const vis = await tableIsVisible(lt.target, dbName, table);
  if ("error" in vis) return { error: vis.error };
  const s = await fetchStructure(lt.target, dbName, table);
  if ("error" in s) return { error: s.error };
  return { structure: s.structure };
}

/** Validate a set of supplied column names against the real column list, keeping
 *  only real columns and preserving the caller's order. */
function keepValidColumns(supplied: string[], real: Set<string>): string[] {
  return supplied.filter((c) => real.has(c));
}

/** INSERT a row. `values` is column→value (null = SQL NULL); unknown columns are
 *  dropped, values are bound as `?` params. Owner-or-admin + not-impersonating. */
export async function dbmgrInsertRow(accountId: string, dbName: string, table: string, values: Record<string, DbCellValue>): Promise<DbMgrResult> {
  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
  const lt = await liveTarget(accountId, dbName);
  if ("error" in lt) return { ...empty, error: lt.error };
  if (lt.mode === "sandbox") return { ...empty, ok: true };
  const vis = await tableIsVisible(lt.target, dbName, table);
  if ("error" in vis) return { ...empty, error: vis.error };
  const s = await fetchStructure(lt.target, dbName, table);
  if ("error" in s) return { ...empty, error: s.error };

  const real = new Set(s.structure.columns.map((c) => c.name));
  const cols = keepValidColumns(Object.keys(values ?? {}), real);
  if (cols.length === 0) return { ...empty, error: "Provide at least one column value." };
  const params = cols.map((c) => values[c]);
  const res = await runScopedSql(lt.target, dbName, insertRowSql(table, cols), params);
  if (res.error) return { ...res, error: res.error };
  return { ...res, ok: true };
}

/** Resolve the WHERE columns that identify an existing row: prefer the PRIMARY
 *  KEY (when every PK column is present in `where`), else fall back to every
 *  supplied real column. Returns [] when the row can't be safely identified. */
function whereColumnsFor(where: Record<string, DbCellValue>, structure: DbMgrStructure, real: Set<string>): string[] {
  const supplied = keepValidColumns(Object.keys(where ?? {}), real);
  const pk = structure.primaryKey;
  if (pk.length > 0 && pk.every((c) => c in (where ?? {}))) return pk;
  return supplied;
}

/** UPDATE one row. `where` identifies the row (original values); `changes` are the
 *  new column→value pairs. Both bound as `?` params, LIMIT 1 on the write. */
export async function dbmgrUpdateRow(
  accountId: string,
  dbName: string,
  table: string,
  where: Record<string, DbCellValue>,
  changes: Record<string, DbCellValue>,
): Promise<DbMgrResult> {
  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
  const lt = await liveTarget(accountId, dbName);
  if ("error" in lt) return { ...empty, error: lt.error };
  if (lt.mode === "sandbox") return { ...empty, ok: true };
  const vis = await tableIsVisible(lt.target, dbName, table);
  if ("error" in vis) return { ...empty, error: vis.error };
  const s = await fetchStructure(lt.target, dbName, table);
  if ("error" in s) return { ...empty, error: s.error };

  const real = new Set(s.structure.columns.map((c) => c.name));
  const setCols = keepValidColumns(Object.keys(changes ?? {}), real);
  if (setCols.length === 0) return { ...empty, error: "No changes to save." };
  const whereCols = whereColumnsFor(where, s.structure, real);
  if (whereCols.length === 0) return { ...empty, error: "Can't identify which row to update." };

  const params = [...setCols.map((c) => changes[c]), ...whereCols.map((c) => where[c])];
  const res = await runScopedSql(lt.target, dbName, updateRowSql(table, setCols, whereCols), params);
  if (res.error) return { ...res, error: res.error };
  return { ...res, ok: true };
}

/** DELETE one row identified by `where` (original values). LIMIT 1 on the write. */
export async function dbmgrDeleteRow(accountId: string, dbName: string, table: string, where: Record<string, DbCellValue>): Promise<DbMgrResult> {
  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
  const lt = await liveTarget(accountId, dbName);
  if ("error" in lt) return { ...empty, error: lt.error };
  if (lt.mode === "sandbox") return { ...empty, ok: true };
  const vis = await tableIsVisible(lt.target, dbName, table);
  if ("error" in vis) return { ...empty, error: vis.error };
  const s = await fetchStructure(lt.target, dbName, table);
  if ("error" in s) return { ...empty, error: s.error };

  const real = new Set(s.structure.columns.map((c) => c.name));
  const whereCols = whereColumnsFor(where, s.structure, real);
  if (whereCols.length === 0) return { ...empty, error: "Can't identify which row to delete." };
  const params = whereCols.map((c) => where[c]);
  const res = await runScopedSql(lt.target, dbName, deleteRowSql(table, whereCols), params);
  if (res.error) return { ...res, error: res.error };
  return { ...res, ok: true };
}

/** Build a downloadable SQL dump of a single table (CREATE TABLE + a bounded set
 *  of INSERTs) via the scoped connection — no root, no mysqldump. Values are
 *  escaped by the mysql2 string-escaper. Bounded by the transport's row cap.
 *  Owner-or-admin + not-impersonating. */
export async function dbmgrExportTable(accountId: string, dbName: string, table: string): Promise<{ error?: string; filename?: string; sql?: string; truncated?: boolean }> {
  const lt = await liveTarget(accountId, dbName);
  if ("error" in lt) return { error: lt.error };
  if (lt.mode === "sandbox") {
    return { filename: `${table}.sql`, sql: `-- Nxeon DB Studio (sandbox) export of \`${table}\`\n`, truncated: false };
  }
  const vis = await tableIsVisible(lt.target, dbName, table);
  if ("error" in vis) return { error: vis.error };

  const create = await runScopedSql(lt.target, dbName, showCreateTableSql(table));
  if (create.error) return { error: create.error };
  // SHOW CREATE TABLE returns one row: [Table, "Create Table"].
  const createStmt = create.rows[0]?.[1] ?? "";

  const s = await fetchStructure(lt.target, dbName, table);
  if ("error" in s) return { error: s.error };
  const colNames = s.structure.columns.map((c) => c.name);

  const data = await runScopedSql(lt.target, dbName, dumpSelectSql(table));
  if (data.error) return { error: data.error };

  const lines: string[] = [];
  lines.push(`-- Nxeon DB Studio export`);
  lines.push(`-- database: ${dbName}`);
  lines.push(`-- table:    ${table}`);
  lines.push(`-- generated: ${new Date().toISOString()}`);
  lines.push(`-- rows:     ${data.rows.length}${data.truncated ? ` (truncated at ${data.rows.length})` : ""}`);
  lines.push("");
  lines.push("SET FOREIGN_KEY_CHECKS=0;");
  lines.push(`DROP TABLE IF EXISTS ${quoteIdent(table)};`);
  lines.push(`${createStmt};`);
  lines.push("");
  if (data.rows.length > 0) {
    const colList = colNames.map((c) => quoteIdent(c)).join(", ");
    for (const row of data.rows) {
      const vals = row.map((cell) => dumpValueLiteral(cell)).join(", ");
      lines.push(`INSERT INTO ${quoteIdent(table)} (${colList}) VALUES (${vals});`);
    }
  }
  lines.push("");
  lines.push("SET FOREIGN_KEY_CHECKS=1;");
  return { filename: `${table}.sql`, sql: lines.join("\n"), truncated: data.truncated };
}

