/** A bounded page of a table's rows. `offset`/`limit` are clamped to integers by
 *  the caller; embedded here as plain numbers (never strings). An optional ORDER
 *  BY column is backtick-quoted — the CALLER must have validated it by membership
 *  against the table's real columns first; `dir` is coerced to a literal keyword. */
export function browseTableSql(table: string, limit: number, offset: number, order?: { col: string; dir: "ASC" | "DESC" }): string {
  const lim = Math.max(1, Math.min(BROWSE_PAGE_SIZE, Math.floor(limit)));
  const off = Math.max(0, Math.floor(offset));
  const orderClause = order ? ` ORDER BY ${quoteIdent(order.col)} ${order.dir === "DESC" ? "DESC" : "ASC"}` : "";
  return `SELECT * FROM ${quoteIdent(table)}${orderClause} LIMIT ${lim} OFFSET ${off};`;
}

