  if (!rlOk(user.id, accountId)) return { error: "Too many requests — slow down a moment." };
  const p = Math.max(0, Math.floor(Number(page) || 0));
  const dir: "ASC" | "DESC" = sortDir === "DESC" ? "DESC" : "ASC";

  if (SANDBOX) {
    const demo = sandboxResult("select");
    return { columns: demo.columns, rows: demo.rows, total: demo.rows.length, page: p, pageSize: BROWSE_PAGE_SIZE, truncated: false, sortColumn: sortColumn ?? null, sortDir: dir };
  }
  const target = dbTargetFor(ctx.a);
  if (!target) return { error: "The database manager is still being prepared." };

  // Membership check: the table MUST be one the scoped user can actually see.
  const listed = await runScopedSql(target, dbName, showTablesSql());
  if (listed.error) return { error: listed.error };
  const tables = listed.rows.map((r) => r[0]);
  if (!tables.includes(table)) return { error: "Unknown table." };

  // A sort column, if given, is validated by MEMBERSHIP against the table's real
  // columns before it can be backtick-quoted into ORDER BY (never interpolated raw).
  let order: { col: string; dir: "ASC" | "DESC" } | undefined;
  if (sortColumn && isPlausibleTableName(sortColumn)) {
    const colsRes = await runScopedSql(target, dbName, showFullColumnsSql(table));
    if (!colsRes.error && colsRes.rows.map((r) => r[0]).includes(sortColumn)) {
      order = { col: sortColumn, dir };
    }
  }

  const res = await runScopedSql(target, dbName, browseTableSql(table, BROWSE_PAGE_SIZE, p * BROWSE_PAGE_SIZE, order));
  if (res.error) return { error: res.error };
  const countRes = await runScopedSql(target, dbName, countTableSql(table));
  const total = countRes.error ? null : Number(countRes.rows[0]?.[0] ?? "0");
  return { columns: res.columns, rows: res.rows, total: Number.isFinite(total as number) ? (total as number) : null, page: p, pageSize: BROWSE_PAGE_SIZE, truncated: res.truncated, sortColumn: order?.col ?? null, sortDir: dir };
}

