"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Badge } from "@/components/ui/primitives";
import {
  ensureDbManager,
  dbmgrStatus,
  dbmgrListDatabases,
  dbmgrTableCounts,
  dbmgrBrowseTable,
  dbmgrRunSql,
  dbmgrTableStructure,
  dbmgrInsertRow,
  dbmgrUpdateRow,
  dbmgrDeleteRow,
  dbmgrExportTable,
  type DbMgrDatabase,
  type DbMgrTableInfo,
  type DbMgrStructure,
  type DbMgrColumn,
  type DbCellValue,
} from "@/lib/actions-hosting-db";

/**
 * Nxeon DB Studio — the PROPRIETARY, in-portal database manager (a phpMyAdmin-class
 * experience with the Nxeon design system). Every action runs SERVER-SIDE as the
 * account's scoped `<username>_mgr` MySQL user over an SSH-tunnelled mysql2 session
 * (see lib/hosting-db.ts): the browser never holds a DB credential and the grant is
 * the isolation boundary, so it can only ever touch this account's own databases.
 */
export function DbManager({ accountId }: { accountId: string }) {
  const [status, setStatus] = useState<"loading" | "provisioning" | "ready" | "error">("loading");
  const [statusMsg, setStatusMsg] = useState("");
  const [databases, setDatabases] = useState<DbMgrDatabase[]>([]);
  const [activeDb, setActiveDb] = useState<string>("");
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const [ens, list] = await Promise.all([ensureDbManager(accountId), dbmgrListDatabases(accountId)]);
      if (cancelled) return;
      if (list.databases) {
        setDatabases(list.databases);
        const firstActive = list.databases.find((d) => d.status === "ACTIVE") ?? list.databases[0];
        if (firstActive) setActiveDb(firstActive.name);
      }
      if (ens.error) { setStatus("error"); setStatusMsg(ens.error); return; }
      if (ens.ready) { setStatus("ready"); return; }
      setStatus("provisioning");
    })();
    return () => { cancelled = true; };
  }, [accountId]);

  useEffect(() => {
    if (status !== "provisioning") return;
    let tries = 0;
    pollRef.current = setInterval(async () => {
      tries++;
      const s = await dbmgrStatus(accountId);
      if (s.ready) { setStatus("ready"); if (pollRef.current) clearInterval(pollRef.current); return; }
      if (tries >= 20) { setStatus("error"); setStatusMsg("The database manager is taking longer than expected to set up. Try again shortly."); if (pollRef.current) clearInterval(pollRef.current); }
    }, 3000);
    return () => { if (pollRef.current) clearInterval(pollRef.current); };
  }, [status, accountId]);

  const activeDbs = databases.filter((d) => d.status === "ACTIVE");

  return (
    <div className="overflow-hidden rounded-2xl border border-white/[0.07] bg-navy-900/60 backdrop-blur-md">
      {/* Studio header */}
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/[0.06] bg-gradient-to-r from-accent-blue/[0.08] to-brand-500/[0.06] px-4 py-3">
        <div className="flex items-center gap-2.5">
          <span className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-accent-blue to-brand-500 text-[13px] font-bold text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]">N</span>
          <div>
            <h3 className="text-sm font-semibold text-slate-100">Nxeon DB Studio</h3>
            <p className="text-[11px] text-slate-500">Browse, query &amp; edit your databases</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {status === "ready" && <Badge tone="green">connected</Badge>}
          {status === "provisioning" && <Badge tone="amber">preparing</Badge>}
          {status === "error" && <Badge tone="red">unavailable</Badge>}
        </div>
      </div>

      <div className="p-4">
        {status === "loading" && <SkeletonStudio />}
        {status === "provisioning" && (
          <div className="flex items-center gap-3 rounded-xl border border-amber-500/20 bg-amber-500/[0.06] px-4 py-3">
            <Spinner />
            <p className="text-xs text-amber-200">Preparing your secure database connection… this only happens once.</p>
          </div>
        )}
        {status === "error" && (
          <div className="rounded-xl border border-red-500/20 bg-red-500/[0.06] px-4 py-3 text-xs text-red-200">{statusMsg || "The database manager is unavailable right now."}</div>
        )}

        {status === "ready" && databases.length === 0 && (
          <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-10 text-center">
            <DatabaseIcon className="mx-auto mb-3 h-8 w-8 text-brand-300/70" />
            <p className="text-sm font-medium text-slate-200">No databases yet</p>
            <p className="mx-auto mt-1 max-w-sm text-xs text-slate-500">Create your first database below, then come back to browse tables, run queries and edit rows here.</p>
          </div>
        )}

        {status === "ready" && databases.length > 0 && (
          <Studio
            key={activeDb}
            accountId={accountId}
            databases={databases}
            activeDbs={activeDbs}
            activeDb={activeDb}
            onPickDb={setActiveDb}
          />
        )}
      </div>
    </div>
  );
}

/* ================================================================= Studio === */

type MainTab = "browse" | "structure" | "sql";

function Studio({
  accountId,
  databases,
  activeDbs,
  activeDb,
  onPickDb,
}: {
  accountId: string;
  databases: DbMgrDatabase[];
  activeDbs: DbMgrDatabase[];
  activeDb: string;
  onPickDb: (db: string) => void;
}) {
  const [tables, setTables] = useState<DbMgrTableInfo[]>([]);
  const [tablesErr, setTablesErr] = useState("");
  const [tablesBusy, setTablesBusy] = useState(true);
  const [filter, setFilter] = useState("");
  const [activeTable, setActiveTable] = useState<string>("");
  const [tab, setTab] = useState<MainTab>("browse");

  const loadTables = useCallback(async () => {
    setTablesBusy(true); setTablesErr("");
    const res = await dbmgrTableCounts(accountId, activeDb);
    setTablesBusy(false);
    if (res.error) { setTablesErr(res.error); setTables([]); return; }
    setTables(res.tables ?? []);
  }, [accountId, activeDb]);

  useEffect(() => { loadTables(); }, [loadTables]);

  const filtered = useMemo(() => {
    const q = filter.trim().toLowerCase();
    return q ? tables.filter((t) => t.name.toLowerCase().includes(q)) : tables;
  }, [tables, filter]);

  function openTable(name: string) {
    setActiveTable(name);
    setTab((t) => (t === "sql" ? "browse" : t));
  }

  return (
    <div className="grid gap-4 lg:grid-cols-[16rem_minmax(0,1fr)]">
      {/* Sidebar */}
      <aside className="flex flex-col gap-3">
        {/* Database picker */}
        <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
          <p className="section-label mb-2 flex items-center gap-1.5"><DatabaseIcon className="h-3.5 w-3.5" /> Database</p>
          {activeDbs.length > 1 ? (
            <select className="input py-2 text-xs" value={activeDb} onChange={(e) => onPickDb(e.target.value)}>
              {databases.map((d) => (
                <option key={d.name} value={d.name} disabled={d.status !== "ACTIVE"}>
                  {d.name}{d.status !== "ACTIVE" ? ` (${d.status.toLowerCase()})` : ""}
                </option>
              ))}
            </select>
          ) : (
            <p className="truncate rounded-lg border border-white/[0.06] bg-navy-900/60 px-2.5 py-2 font-mono text-xs text-slate-200" title={activeDb}>{activeDb}</p>
          )}
        </div>

        {/* Tables tree */}
        <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
          <div className="mb-2 flex items-center justify-between">
            <p className="section-label flex items-center gap-1.5"><TableIcon className="h-3.5 w-3.5" /> Tables {tables.length > 0 && <span className="text-slate-600">({tables.length})</span>}</p>
            <button type="button" className="btn-ghost rounded-md px-1.5 py-1 text-[11px]" onClick={loadTables} title="Refresh tables"><RefreshIcon className="h-3.5 w-3.5" /></button>
          </div>
          <div className="relative mb-2">
            <SearchIcon className="pointer-events-none absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-500" />
            <input className="input py-1.5 pl-8 text-xs" placeholder="Filter tables…" value={filter} onChange={(e) => setFilter(e.target.value)} />
          </div>
          {tablesBusy && <div className="space-y-1.5 py-1">{[0, 1, 2, 3].map((i) => <div key={i} className="skeleton h-6" />)}</div>}
          {tablesErr && <p className="rounded-lg border border-red-500/20 bg-red-500/[0.06] px-2 py-1.5 text-[11px] text-red-200">{tablesErr}</p>}
          {!tablesBusy && !tablesErr && tables.length === 0 && <p className="px-1 py-2 text-[11px] text-slate-500">This database has no tables yet. Create one from the SQL tab.</p>}
          {!tablesBusy && !tablesErr && tables.length > 0 && filtered.length === 0 && <p className="px-1 py-2 text-[11px] text-slate-500">No tables match “{filter}”.</p>}
          <ul className="max-h-[22rem] space-y-0.5 overflow-y-auto">
            {filtered.map((t) => {
              const active = activeTable === t.name && tab !== "sql";
              return (
                <li key={t.name}>
                  <button
                    type="button"
                    onClick={() => openTable(t.name)}
                    className={`group flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left transition-colors ${active ? "bg-gradient-to-r from-accent-blue/20 to-brand-500/20 text-brand-100" : "text-slate-300 hover:bg-white/[0.04]"}`}
                    title={t.name}
                  >
                    <TableIcon className={`h-3.5 w-3.5 shrink-0 ${active ? "text-brand-200" : "text-slate-500 group-hover:text-slate-400"}`} />
                    <span className="min-w-0 flex-1 truncate font-mono text-xs">{t.name}</span>
                    {t.rows != null && <span className="shrink-0 rounded-full bg-white/[0.06] px-1.5 py-0.5 text-[10px] tabular-nums text-slate-400">{fmtCount(t.rows)}</span>}
                  </button>
                </li>
              );
            })}
          </ul>
        </div>

        <button
          type="button"
          onClick={() => setTab("sql")}
          className={`flex items-center gap-2 rounded-xl border px-3 py-2.5 text-xs font-semibold transition-colors ${tab === "sql" ? "border-brand-500/40 bg-brand-500/15 text-brand-100" : "border-white/[0.06] bg-white/[0.02] text-slate-300 hover:bg-white/[0.05]"}`}
        >
          <SqlIcon className="h-4 w-4" /> SQL query editor
        </button>
      </aside>

      {/* Main pane */}
      <section className="min-w-0">
        <div className="mb-3 flex flex-wrap items-center gap-1 border-b border-white/[0.06] pb-2">
          <TabButton active={tab === "browse"} disabled={!activeTable} onClick={() => setTab("browse")} icon={<GridIcon className="h-3.5 w-3.5" />}>Browse</TabButton>
          <TabButton active={tab === "structure"} disabled={!activeTable} onClick={() => setTab("structure")} icon={<ColumnsIcon className="h-3.5 w-3.5" />}>Structure</TabButton>
          <TabButton active={tab === "sql"} onClick={() => setTab("sql")} icon={<SqlIcon className="h-3.5 w-3.5" />}>SQL</TabButton>
          {activeTable && tab !== "sql" && (
            <span className="ml-auto flex items-center gap-1.5 font-mono text-xs text-slate-400"><TableIcon className="h-3.5 w-3.5 text-brand-300" />{activeTable}</span>
          )}
        </div>

        {tab === "sql" && <SqlEditor accountId={accountId} dbName={activeDb} onChanged={loadTables} />}
        {tab !== "sql" && !activeTable && (
          <div className="rounded-xl border border-dashed border-white/[0.08] bg-white/[0.01] px-4 py-12 text-center">
            <TableIcon className="mx-auto mb-3 h-7 w-7 text-slate-600" />
            <p className="text-sm text-slate-300">Pick a table to get started</p>
            <p className="mx-auto mt-1 max-w-xs text-xs text-slate-500">Choose a table from the sidebar to browse its rows and edit its structure, or open the SQL editor.</p>
          </div>
        )}
        {tab === "browse" && activeTable && (
          <TableBrowser key={`${activeDb}/${activeTable}`} accountId={accountId} dbName={activeDb} table={activeTable} onDataChanged={loadTables} />
        )}
        {tab === "structure" && activeTable && (
          <StructureView key={`${activeDb}/${activeTable}/s`} accountId={accountId} dbName={activeDb} table={activeTable} />
        )}
      </section>
    </div>
  );
}

/* ============================================================ TableBrowser === */

type Sort = { col: string; dir: "ASC" | "DESC" } | null;

function TableBrowser({ accountId, dbName, table, onDataChanged }: { accountId: string; dbName: string; table: string; onDataChanged: () => void }) {
  const [page, setPage] = useState(0);
  const [sort, setSort] = useState<Sort>(null);
  const [reload, setReload] = useState(0);
  const [data, setData] = useState<{ columns: string[]; rows: string[][]; total: number | null; pageSize: number; truncated: boolean } | null>(null);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);

  // Structure powers the row editor (columns, PK). Loaded once per table.
  const [structure, setStructure] = useState<DbMgrStructure | null>(null);
  useEffect(() => {
    let cancelled = false;
    dbmgrTableStructure(accountId, dbName, table).then((r) => { if (!cancelled && r.structure) setStructure(r.structure); });
    return () => { cancelled = true; };
  }, [accountId, dbName, table]);

  // Row-editor modal state.
  const [editor, setEditor] = useState<{ mode: "insert" | "edit"; original: Record<string, DbCellValue> | null } | null>(null);
  const [confirmDel, setConfirmDel] = useState<{ row: Record<string, DbCellValue>; label: string } | null>(null);
  const [busyMsg, setBusyMsg] = useState("");

  useEffect(() => {
    let cancelled = false;
    setBusy(true); setErr("");
    dbmgrBrowseTable(accountId, dbName, table, page, sort?.col, sort?.dir).then((res) => {
      if (cancelled) return;
      setBusy(false);
      if (res.error) { setErr(res.error); setData(null); return; }
      setData({ columns: res.columns ?? [], rows: res.rows ?? [], total: res.total ?? null, pageSize: res.pageSize ?? 50, truncated: !!res.truncated });
    });
    return () => { cancelled = true; };
  }, [accountId, dbName, table, page, sort, reload]);

  const total = data?.total ?? null;
  const pageSize = data?.pageSize ?? 50;
  const maxPage = total != null ? Math.max(0, Math.ceil(total / pageSize) - 1) : (data && data.rows.length === pageSize ? page + 1 : page);
  const from = data && data.rows.length ? page * pageSize + 1 : 0;
  const to = data ? page * pageSize + data.rows.length : 0;

  function toggleSort(col: string) {
    setPage(0);
    setSort((s) => (!s || s.col !== col ? { col, dir: "ASC" } : s.dir === "ASC" ? { col, dir: "DESC" } : null));
  }

  function rowRecord(r: string[]): Record<string, DbCellValue> {
    const cols = data?.columns ?? [];
    const rec: Record<string, DbCellValue> = {};
    cols.forEach((c, i) => { rec[c] = r[i] === NULL_CELL ? null : (r[i] ?? ""); });
    return rec;
  }

  async function doDelete() {
    if (!confirmDel) return;
    setBusyMsg("Deleting row…");
    const res = await dbmgrDeleteRow(accountId, dbName, table, confirmDel.row);
    setBusyMsg("");
    setConfirmDel(null);
    if (res.error) { setErr(res.error); return; }
    setReload((n) => n + 1);
    onDataChanged();
  }

  async function exportDump() {
    setBusyMsg("Building SQL dump…");
    const res = await dbmgrExportTable(accountId, dbName, table);
    setBusyMsg("");
    if (res.error) { setErr(res.error); return; }
    downloadText(res.filename ?? `${table}.sql`, res.sql ?? "");
  }

  return (
    <div>
      {/* Toolbar */}
      <div className="mb-2 flex flex-wrap items-center gap-2">
        <button className="btn-primary px-3 py-1.5 text-xs" disabled={!structure} onClick={() => setEditor({ mode: "insert", original: null })}><PlusIcon className="h-3.5 w-3.5" /> Insert row</button>
        <button className="btn-secondary px-3 py-1.5 text-xs" onClick={exportDump}><DownloadIcon className="h-3.5 w-3.5" /> Export</button>
        <button className="btn-ghost rounded-lg px-2 py-1.5 text-xs" onClick={() => setReload((n) => n + 1)} title="Refresh"><RefreshIcon className="h-3.5 w-3.5" /></button>
        <div className="ml-auto flex items-center gap-1.5 text-xs">
          {total != null && <span className="text-slate-500">{total.toLocaleString()} rows</span>}
          <div className="flex items-center gap-1">
            <button className="btn-secondary px-2 py-1 text-xs disabled:opacity-40" disabled={busy || page === 0} onClick={() => setPage((p) => Math.max(0, p - 1))} title="Previous page"><ChevronIcon className="h-3.5 w-3.5 rotate-180" /></button>
            <span className="min-w-[3.5rem] text-center text-[11px] tabular-nums text-slate-400">{from}–{to}</span>
            <button className="btn-secondary px-2 py-1 text-xs disabled:opacity-40" disabled={busy || page >= maxPage} onClick={() => setPage((p) => p + 1)} title="Next page"><ChevronIcon className="h-3.5 w-3.5" /></button>
          </div>
        </div>
      </div>

      {err && <ErrorBanner msg={err} onClose={() => setErr("")} />}

      {busy && !data ? (
        <GridSkeleton />
      ) : data ? (
        <DataGrid
          columns={data.columns}
          rows={data.rows}
          sort={sort}
          onSort={toggleSort}
          onEdit={(r) => setEditor({ mode: "edit", original: rowRecord(r) })}
          onDelete={(r) => setConfirmDel({ row: rowRecord(r), label: firstCells(r) })}
          truncated={data.truncated}
        />
      ) : null}

      {editor && structure && (
        <RowEditor
          mode={editor.mode}
          table={table}
          structure={structure}
          original={editor.original}
          onClose={() => setEditor(null)}
          onSave={async (payload) => {
            if (editor.mode === "insert") {
              const res = await dbmgrInsertRow(accountId, dbName, table, payload.values);
              if (res.error) return res.error;
            } else {
              const res = await dbmgrUpdateRow(accountId, dbName, table, editor.original ?? {}, payload.changes);
              if (res.error) return res.error;
            }
            setEditor(null);
            setReload((n) => n + 1);
            onDataChanged();
            return null;
          }}
        />
      )}

      {confirmDel && (
        <ConfirmDialog
          title="Delete this row?"
          body={<>This permanently deletes the row <span className="font-mono text-slate-200">{confirmDel.label}</span>. This can’t be undone.</>}
          confirmLabel="Delete row"
          danger
          onCancel={() => setConfirmDel(null)}
          onConfirm={doDelete}
        />
      )}

      {busyMsg && <BusyOverlay msg={busyMsg} />}
    </div>
  );
}

/* ================================================================ DataGrid === */

function DataGrid({
  columns,
  rows,
  sort,
  onSort,
  onEdit,
  onDelete,
  truncated,
}: {
  columns: string[];
  rows: string[][];
  sort: Sort;
  onSort: (col: string) => void;
  onEdit: (r: string[]) => void;
  onDelete: (r: string[]) => void;
  truncated: boolean;
}) {
  if (columns.length === 0) return <p className="text-xs text-slate-500">No columns.</p>;
  return (
    <div>
      <div className="overflow-x-auto rounded-xl border border-white/[0.06]">
        <table className="min-w-full text-left text-xs">
          <thead className="sticky top-0 bg-navy-900/95 backdrop-blur">
            <tr>
              <th className="w-20 border-b border-white/[0.06] px-2 py-2 text-[11px] font-semibold uppercase tracking-wider text-slate-600">Actions</th>
              {columns.map((c, i) => {
                const active = sort?.col === c;
                return (
                  <th key={i} className="whitespace-nowrap border-b border-white/[0.06] px-3 py-2">
                    <button type="button" onClick={() => onSort(c)} className="group inline-flex items-center gap-1 font-semibold text-slate-300 hover:text-white">
                      {c}
                      <span className={`text-[10px] ${active ? "text-brand-300" : "text-slate-600 group-hover:text-slate-500"}`}>{active ? (sort!.dir === "ASC" ? "▲" : "▼") : "↕"}</span>
                    </button>
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {rows.length === 0 && (
              <tr><td colSpan={columns.length + 1} className="px-3 py-6 text-center text-slate-500">No rows in this table.</td></tr>
            )}
            {rows.map((r, ri) => (
              <tr key={ri} className="border-t border-white/[0.04] transition-colors odd:bg-white/[0.01] hover:bg-white/[0.03]">
                <td className="whitespace-nowrap px-2 py-1">
                  <div className="flex items-center gap-1">
                    <button type="button" onClick={() => onEdit(r)} className="rounded-md p-1 text-slate-500 hover:bg-brand-500/15 hover:text-brand-200" title="Edit row"><EditIcon className="h-3.5 w-3.5" /></button>
                    <button type="button" onClick={() => onDelete(r)} className="rounded-md p-1 text-slate-500 hover:bg-red-500/15 hover:text-red-300" title="Delete row"><TrashIcon className="h-3.5 w-3.5" /></button>
                  </div>
                </td>
                {columns.map((_, ci) => (
                  <td key={ci} className="max-w-[22rem] truncate border-t border-white/[0.03] px-3 py-1.5 font-mono text-slate-300" title={cell(r[ci])}>
                    {r[ci] === NULL_CELL ? <span className="italic text-slate-600">NULL</span> : cell(r[ci])}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {truncated && <p className="mt-1.5 text-[11px] text-amber-300">Results truncated at the row/size cap — use the SQL tab with a tighter WHERE/LIMIT to see more.</p>}
    </div>
  );
}

/* ============================================================ StructureView === */

function StructureView({ accountId, dbName, table }: { accountId: string; dbName: string; table: string }) {
  const [structure, setStructure] = useState<DbMgrStructure | null>(null);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(true);

  useEffect(() => {
    let cancelled = false;
    setBusy(true); setErr("");
    dbmgrTableStructure(accountId, dbName, table).then((r) => {
      if (cancelled) return;
      setBusy(false);
      if (r.error) { setErr(r.error); return; }
      setStructure(r.structure ?? null);
