              {["Column", "Type", "Null", "Key", "Default", "Extra"].map((h) => (
                <th key={h} className="whitespace-nowrap border-b border-white/[0.06] px-3 py-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500">{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {structure.columns.map((c) => (
              <tr key={c.name} className="border-t border-white/[0.04] odd:bg-white/[0.01]">
                <td className="whitespace-nowrap px-3 py-1.5 font-mono font-medium text-slate-200">
                  <span className="inline-flex items-center gap-1.5">{c.key === "PRI" && <KeyIcon className="h-3 w-3 text-amber-300" />}{c.name}</span>
                </td>
                <td className="whitespace-nowrap px-3 py-1.5 font-mono text-brand-200/90">{c.type}</td>
                <td className="px-3 py-1.5 text-slate-400">{c.nullable ? "YES" : "NO"}</td>
                <td className="px-3 py-1.5">{keyBadge(c)}</td>
