            <table className="min-w-full text-left text-xs">
              <thead className="bg-white/[0.03]">
                <tr>
                  {["Name", "Columns", "Unique"].map((h) => (
                    <th key={h} className="border-b border-white/[0.06] px-3 py-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {structure.indexes.map((ix) => (
                  <tr key={ix.name} className="border-t border-white/[0.04] odd:bg-white/[0.01]">
                    <td className="whitespace-nowrap px-3 py-1.5 font-mono text-slate-200">{ix.name === "PRIMARY" ? <Badge tone="amber">PRIMARY</Badge> : ix.name}</td>
                    <td className="px-3 py-1.5 font-mono text-slate-400">{ix.columns.join(", ")}</td>
