/* =============================================================== RowEditor === */

type FieldState = { value: string; isNull: boolean; include: boolean };

function RowEditor({
  mode,
  table,
  structure,
  original,
  onClose,
  onSave,
}: {
  mode: "insert" | "edit";
  table: string;
  structure: DbMgrStructure;
  original: Record<string, DbCellValue> | null;
  onClose: () => void;
  onSave: (payload: { values: Record<string, DbCellValue>; changes: Record<string, DbCellValue> }) => Promise<string | null>;
}) {
  const [fields, setFields] = useState<Record<string, FieldState>>(() => {
    const init: Record<string, FieldState> = {};
    for (const c of structure.columns) {
      if (mode === "edit" && original) {
        const v = original[c.name];
        init[c.name] = { value: v === null ? "" : (v ?? ""), isNull: v === null, include: true };
      } else {
        // Insert: pre-omit auto_increment / defaulted columns so the DB fills them.
        const auto = /auto_increment/i.test(c.extra) || c.default !== null;
        init[c.name] = { value: "", isNull: false, include: !auto };
      }
    }
    return init;
  });
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);

  function set(name: string, patch: Partial<FieldState>) {
    setFields((f) => ({ ...f, [name]: { ...f[name], ...patch } }));
  }

  async function submit() {
    setBusy(true); setErr("");
    const values: Record<string, DbCellValue> = {};
    const changes: Record<string, DbCellValue> = {};
    for (const c of structure.columns) {
      const f = fields[c.name];
      const val: DbCellValue = f.isNull ? null : f.value;
      if (mode === "insert") {
        if (f.include) values[c.name] = val;
      } else {
        const orig = original ? original[c.name] ?? null : null;
        const origNorm = orig === null ? null : String(orig);
        const nextNorm = f.isNull ? null : f.value;
        if (origNorm !== nextNorm) changes[c.name] = val;
      }
    }
    if (mode === "edit" && Object.keys(changes).length === 0) { setBusy(false); setErr("No changes to save."); return; }
    if (mode === "insert" && Object.keys(values).length === 0) { setBusy(false); setErr("Set at least one column."); return; }
    const e = await onSave({ values, changes });
    setBusy(false);
    if (e) setErr(e);
  }

  return (
    <Modal onClose={onClose} title={mode === "insert" ? `Insert row into ${table}` : `Edit row in ${table}`} wide>
      <div className="max-h-[60vh] space-y-2.5 overflow-y-auto pr-1">
        {structure.columns.map((c) => {
          const f = fields[c.name];
          return (
            <div key={c.name} className="grid grid-cols-[10rem_1fr] items-start gap-3">
              <div className="pt-2">
                <p className="flex items-center gap-1.5 font-mono text-xs text-slate-200">
                  {c.key === "PRI" && <KeyIcon className="h-3 w-3 text-amber-300" />}{c.name}
                </p>
                <p className="mt-0.5 font-mono text-[10px] text-slate-500">{c.type}{/auto_increment/i.test(c.extra) ? " · auto" : ""}{!c.nullable ? " · not null" : ""}</p>
              </div>
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  {isTextarea(c) ? (
                    <textarea className="input h-20 font-mono text-xs disabled:opacity-40" disabled={f.isNull} value={f.value} onChange={(e) => set(c.name, { value: e.target.value, include: true })} />
                  ) : (
                    <input className="input py-2 font-mono text-xs disabled:opacity-40" disabled={f.isNull} value={f.value} placeholder={mode === "insert" && !f.include ? "(default)" : ""} onChange={(e) => set(c.name, { value: e.target.value, include: true })} />
                  )}
                  {c.nullable && (
                    <label className="flex shrink-0 cursor-pointer items-center gap-1 text-[11px] text-slate-400">
                      <input type="checkbox" checked={f.isNull} onChange={(e) => set(c.name, { isNull: e.target.checked, include: true })} className="accent-brand-500" /> NULL
                    </label>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>
      {err && <p className="mt-3 whitespace-pre-wrap rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 font-mono text-[11px] text-red-200">{err}</p>}
      <div className="mt-4 flex items-center justify-end gap-2">
        <button className="btn-ghost px-3 py-2 text-xs" onClick={onClose} disabled={busy}>Cancel</button>
        <button className="btn-primary px-4 py-2 text-xs" onClick={submit} disabled={busy}>{busy ? "Saving…" : mode === "insert" ? "Insert row" : "Save changes"}</button>
      </div>
    </Modal>
  );
}

/* ================================================================ SqlEditor === */

const DESTRUCTIVE_RE = /^\s*(drop|truncate|delete|alter|update|replace|grant|revoke|create)\b/i;

function SqlEditor({ accountId, dbName, onChanged }: { accountId: string; dbName: string; onChanged: () => void }) {
  const [sql, setSql] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [note, setNote] = useState("");
  const [result, setResult] = useState<{ columns: string[]; rows: string[][]; truncated: boolean } | null>(null);
  const [pendingConfirm, setPendingConfirm] = useState(false);

  async function execute() {
    setBusy(true); setErr(""); setNote(""); setResult(null); setPendingConfirm(false);
    const res = await dbmgrRunSql(accountId, dbName, sql);
    setBusy(false);
    if (res.error) { setErr(res.error); return; }
    if (res.columns.length === 0) {
      setNote(`Statement executed successfully · ${res.elapsedMs} ms`);
      onChanged();
      return;
    }
    setResult({ columns: res.columns, rows: res.rows, truncated: res.truncated });
    setNote(`${res.rows.length} row${res.rows.length === 1 ? "" : "s"}${res.truncated ? "+" : ""} · ${res.elapsedMs} ms`);
  }

  function run() {
    if (!sql.trim()) return;
    if (DESTRUCTIVE_RE.test(sql)) { setPendingConfirm(true); return; }
    execute();
  }

  return (
    <div>
      <div className="mb-2 flex items-center gap-2 text-[11px] text-slate-500">
        <SqlIcon className="h-3.5 w-3.5 text-brand-300" />
        Running against <span className="font-mono text-slate-300">{dbName}</span> as your scoped database user — queries can only ever touch your own databases.
      </div>
      <div className="overflow-hidden rounded-xl border border-white/[0.08] focus-within:border-brand-400/50 focus-within:ring-2 focus-within:ring-brand-500/20">
        <textarea
          className="block h-36 w-full resize-y bg-navy-900/80 px-3.5 py-3 font-mono text-xs text-slate-100 outline-none placeholder:text-slate-600"
          placeholder="SELECT * FROM your_table LIMIT 20;"
          spellCheck={false}
          value={sql}
          onChange={(e) => setSql(e.target.value)}
          onKeyDown={(e) => { if ((e.metaKey || e.ctrlKey) && e.key === "Enter") run(); }}
        />
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <button className="btn-primary px-4 py-1.5 text-xs" disabled={busy || !sql.trim()} onClick={run}><PlayIcon className="h-3.5 w-3.5" />{busy ? "Running…" : "Run"}</button>
        <span className="kbd">⌘/Ctrl + Enter</span>
        <button className="btn-ghost px-2 py-1.5 text-xs" disabled={busy || !sql} onClick={() => { setSql(""); setResult(null); setNote(""); setErr(""); }}>Clear</button>
        {note && <span className="ml-auto text-[11px] text-slate-400">{note}</span>}
      </div>

      {err && <div className="mt-3"><ErrorBanner msg={err} onClose={() => setErr("")} /></div>}
      {result && (
        <div className="mt-3">
          <ResultGrid columns={result.columns} rows={result.rows} truncated={result.truncated} />
        </div>
      )}

      {pendingConfirm && (
        <ConfirmDialog
          title="Run this statement?"
          body={<>This looks like it modifies data or schema. It runs as your scoped database user, but the change may be hard to undo. Continue?</>}
          confirmLabel="Run statement"
          danger
          onCancel={() => setPendingConfirm(false)}
          onConfirm={execute}
        />
      )}
    </div>
  );
}

function ResultGrid({ columns, rows, truncated }: { columns: string[]; rows: string[][]; truncated: boolean }) {
  if (columns.length === 0) return <p className="text-xs text-slate-500">No columns.</p>;
  return (
    <div>
      <div className="overflow-x-auto rounded-xl border border-white/[0.06]">
        <table className="min-w-full text-left text-xs">
          <thead className="bg-white/[0.03]">
            <tr>{columns.map((c, i) => <th key={i} className="whitespace-nowrap border-b border-white/[0.06] px-3 py-2 font-semibold text-slate-300">{c}</th>)}</tr>
          </thead>
          <tbody>
            {rows.length === 0 && <tr><td colSpan={columns.length} className="px-3 py-4 text-center text-slate-500">No rows.</td></tr>}
            {rows.map((r, ri) => (
              <tr key={ri} className="border-t border-white/[0.04] odd:bg-white/[0.01]">
                {columns.map((_, ci) => (
                  <td key={ci} className="max-w-[22rem] truncate border-t border-white/[0.03] px-3 py-1.5 font-mono text-slate-300" title={cell(r[ci])}>
                    {r[ci] === NULL_CELL ? <span className="italic text-slate-600">NULL</span> : cell(r[ci])}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {truncated && <p className="mt-1.5 text-[11px] text-amber-300">Results truncated — refine with a tighter LIMIT or WHERE to see more.</p>}
    </div>
  );
}

