    <div className="grid gap-4 lg:grid-cols-[16rem_minmax(0,1fr)]">
      <div className="space-y-2">{[0, 1, 2, 3, 4, 5].map((i) => <div key={i} className="skeleton h-8" />)}</div>
      <div className="space-y-2"><div className="skeleton h-8 w-40" />{[0, 1, 2, 3, 4].map((i) => <div key={i} className="skeleton h-6" />)}</div>
    </div>
