/* helpers */
const NULL_CELL = " NULL ";
function cell(v: string | undefined): string {
  if (v === undefined) return "";
  if (v === NULL_CELL) return "NULL";
  return v;
}
function firstCells(r: string[]): string {
  return r.slice(0, 3).map((c) => (c === NULL_CELL ? "NULL" : c)).join(", ") + (r.length > 3 ? "…" : "");
}
function fmtCount(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}k`;
  return String(n);
}
function isTextarea(c: DbMgrColumn): boolean {
  return /text|blob|json/i.test(c.type);
}
function keyBadge(c: DbMgrColumn) {
  if (c.key === "PRI") return <Badge tone="amber">PRIMARY</Badge>;
  if (c.key === "UNI") return <Badge tone="brand">unique</Badge>;
  if (c.key === "MUL") return <Badge tone="slate">index</Badge>;
  return <span className="text-slate-600">·</span>;
}
function downloadText(filename: string, text: string) {
  const blob = new Blob([text], { type: "application/sql" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/* ================================================================== icons === */
type IP = { className?: string };
const S = (p: React.SVGProps<SVGSVGElement>) => ({ fill: "none", stroke: "currentColor", strokeWidth: 1.7, strokeLinecap: "round" as const, strokeLinejoin: "round" as const, viewBox: "0 0 24 24", ...p });
function DatabaseIcon({ className }: IP) { return <svg {...S({ className })}><ellipse cx="12" cy="5" rx="8" ry="3" /><path d="M4 5v6c0 1.7 3.6 3 8 3s8-1.3 8-3V5" /><path d="M4 11v6c0 1.7 3.6 3 8 3s8-1.3 8-3v-6" /></svg>; }
function TableIcon({ className }: IP) { return <svg {...S({ className })}><rect x="3" y="4" width="18" height="16" rx="2" /><path d="M3 10h18M9 10v10M3 15h18" /></svg>; }
function ColumnsIcon({ className }: IP) { return <svg {...S({ className })}><rect x="3" y="4" width="18" height="16" rx="2" /><path d="M9 4v16M15 4v16" /></svg>; }
function GridIcon({ className }: IP) { return <svg {...S({ className })}><rect x="3" y="4" width="18" height="16" rx="2" /><path d="M3 9h18M3 14h18M8 4v16" /></svg>; }
function SqlIcon({ className }: IP) { return <svg {...S({ className })}><path d="m8 8-4 4 4 4M16 8l4 4-4 4M13 6l-2 12" /></svg>; }
function PlayIcon({ className }: IP) { return <svg {...S({ className })}><path d="M6 4l14 8-14 8z" /></svg>; }
function PlusIcon({ className }: IP) { return <svg {...S({ className })}><path d="M12 5v14M5 12h14" /></svg>; }
